import{_ as a,c as t,o as i,ag as o}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1791309864000}'),r={name:"guide/settings.md"};function n(s,e,l,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>nPlyr&#39;s settings window is organized into tabs. This page walks through the ones most people change first.</p><h2 id="appearance-language" tabindex="-1">Appearance &amp; language <a class="header-anchor" href="#appearance-language" aria-label="Permalink to &quot;Appearance &amp; language&quot;">​</a></h2><h3 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h3><p>nPlyr ships with several built-in themes, each keyed to a signature accent color. Switch themes and the entire UI — including every open window — updates immediately. You can also follow the <strong>system appearance</strong> (light / dark) automatically.</p><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>The UI is localized into <strong>25 languages</strong>. Changing the language takes effect instantly across all open windows and the menu bar — no restart required. (This live switch is handled by rebuilding each window&#39;s view when the language changes.)</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><ul><li><strong>Browser user-agent</strong> — choose <em>Auto</em>, <em>Mobile</em>, <em>Desktop (PC)</em>, or paste a <strong>custom</strong> UA. The UA is used by the <a href="/guide/browser.html">sniffer</a> and by playback/parsing when needed. A rule may also specify its own UA; the gear setting overrides it only when you choose to follow the rule&#39;s value.</li><li><strong>File associations</strong> — let nPlyr open local video and audio files (<code>.mp4</code>, <code>.mkv</code>, <code>.mov</code>, <code>.m4v</code>, <code>.webm</code>, <code>.flv</code>, <code>.mka</code>, …) when you double-click them in Finder.</li></ul><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><ul><li>Default save location for downloaded media.</li><li>Whether <strong>progressive playback</strong> is offered.</li><li>Quality default and whether to download subtitles automatically.</li></ul><h2 id="player" tabindex="-1">Player <a class="header-anchor" href="#player" aria-label="Permalink to &quot;Player&quot;">​</a></h2><ul><li>Default playback speed.</li><li>Gesture preferences (trackpad / touch sensitivity).</li><li>PiP and AirPlay defaults.</li></ul><h2 id="ad-blocking" tabindex="-1">Ad-blocking <a class="header-anchor" href="#ad-blocking" aria-label="Permalink to &quot;Ad-blocking&quot;">​</a></h2><p>Subscribe to Chrome-compatible filter lists. nPlyr filters requests in the browser and during playback. Ad-blocking and progressive playback are mutually exclusive.</p><h2 id="mini-programs" tabindex="-1">Mini-programs <a class="header-anchor" href="#mini-programs" aria-label="Permalink to &quot;Mini-programs&quot;">​</a></h2><p>Manage the imported mini-programs and rule sources: add, edit, reorder and delete. A <strong>free tier</strong> caps the number of mini-programs; unlocking removes the cap and is stored as a one-time purchase. See <a href="/guide/miniapps.html">Mini-Programs</a>.</p>',17)])])}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
